)


def test_normalize_bybit_symbol():
    assert _normalize_bybit_symbol("btc") == "BTCUSDT"
    assert _normalize_bybit_symbol("ETHUSDT") == "ETHUSDT"


def test_external_sentiment_disabled_returns_empty():
    agent = ExternalSentimentAgent({"external_sentiment": {"enabled": False}})
    exchange = MagicMock()
    out = asyncio.run(agent.collect(exchange, ["BTCUSDT"]))
    assert out == []


def test_adanos_to_signal_bullish():
    cfg = {
        "external_sentiment": {
            "enabled": True,
            "cache_sec": 0,
            "coinugget_style": {"enabled": False},
            "adanos": {
                "enabled": True,
                "api_key_env": "ADANOS_API_KEY",
                "min_buzz_score": 50,
                "min_sentiment_abs": 0.1,
            },
        }
    }
    agent = ExternalSentimentAgent(cfg)
    sig = agent._adanos_to_signal(
        {"symbol": "BTC", "buzz_score": 80, "sentiment_score": 0.5},
        price=50000.0,
    )
    assert sig is not None
    assert sig.source == "adanos_reddit"
    assert sig.symbol == "BTCUSDT"
    assert sig.side == "Buy"


def test_adanos_to_signal_low_buzz_skipped():
    agent = ExternalSentimentAgent(
        {"external_sentiment": {"adanos": {"min_buzz_score": 90}}}
    )
    sig = agent._adanos_to_signal(
        {"symbol": "ETH", "buzz_score": 10, "sentiment_score": 0.8},
        price=3000.0,
    )
    assert sig is None


def test_coinugget_style_rsi_buy_signal():
    cfg = {
        "external_sentiment": {
            "enabled": True,
            "cache_sec": 0,
            "coinugget_style": {
                "enabled": True,
                "rsi_period": 14,
                "rsi_oversold": 30,
                "rsi_overbought": 70,
                "volume_spike_mult": 2.0,
                "min_confidence": 0.5,
                "max_symbols": 5,
                "kline_interval": "15",
                "klines_limit": 60,
            },
            "adanos": {"enabled": False},
        }
    }
    agent = ExternalSentimentAgent(cfg)
    closes = [100.0 - i * 2.0 for i in range(40)]
    volumes = [100.0] * 39 + [500.0]
    klines = [
        [0, str(c), str(c + 1), str(c - 1), str(c), str(v), "0"]
        for c, v in zip(closes, volumes)
    ]
    exchange = MagicMock()
    exchange.get_klines = AsyncMock(return_value=klines)
    exchange.get_price = AsyncMock(return_value=100.0)
    out = asyncio.run(agent._coinugget_style_signals(exchange, ["BTCUSDT"]))
    assert len(out) >= 1
    assert out[0].source == "coinugget_style"
    assert out[0].side in ("Buy", "Sell")

